import type { Vec2 } from "../../geometry";

/**
 * Snapping, ported line for line from the engine's SnapEngine
 * (geometry/scene/snapping.py, Phase 4.2) so the browser and the engine pick
 * the same point. The parity test (tests/unit/snap.test.ts) runs both on one
 * fixture set generated by scripts/gen-snap-fixture.py. Change both together.
 *
 * Differences from the engine, all outside the parity set:
 * - The candidate search is limited to features within the tolerance of the
 *   point. Only those can be eligible, so the chosen point is the same.
 * - The UI also passes keep-out zones (the engine scene has none yet).
 */
export const SNAP_KINDS = [
  "vertex",
  "endpoint",
  "edge",
  "midpoint",
  "intersection",
  "parallel",
  "perpendicular",
  "module_edge",
  "row_edge",
  "user_grid"
] as const;
export type SnapKind = (typeof SNAP_KINDS)[number];

const PRIORITY: Record<SnapKind, number> = {
  vertex: 0,
  endpoint: 1,
  intersection: 2,
  midpoint: 3,
  edge: 4,
  module_edge: 5,
  row_edge: 6,
  parallel: 7,
  perpendicular: 8,
  user_grid: 9
};

const EPSILON = 1e-9;

/** Geometry the snapper sees, in the engine's collection order: surfaces, obstacles, reference lines. */
export interface SnapItem {
  id: string;
  points: Vec2[];
  /** Closed polygons (surfaces, obstacles) or open polylines (reference lines). */
  closed: boolean;
  visible?: boolean;
}

export type SupplementalEdge = [sourceId: string, start: Vec2, end: Vec2];

export interface SnapOptions {
  toleranceM: number;
  enabled?: ReadonlySet<SnapKind> | readonly SnapKind[];
  /** Alt held: return the raw point. */
  override?: boolean;
  gridSpacingM?: number | null;
  anchor?: Vec2 | null;
  referenceDirection?: Vec2 | null;
}

export interface SnapResult {
  raw: Vec2;
  point: Vec2;
  applied: boolean;
  kind: SnapKind | null;
  sourceId: string | null;
  featureIndex: number | null;
  distanceM: number;
}

interface Candidate {
  kind: SnapKind;
  point: Vec2;
  distance: number;
  sourceId: string | null;
  featureIndex: number | null;
}

const len = (a: Vec2, b: Vec2) => Math.hypot(b[0] - a[0], b[1] - a[1]);

function orientation(a: Vec2, b: Vec2, c: Vec2) {
  return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);
}

function onSegment(a: Vec2, b: Vec2, p: Vec2) {
  if (Math.abs(orientation(a, b, p)) > EPSILON) return false;
  return (
    Math.min(a[0], b[0]) - EPSILON <= p[0] &&
    p[0] <= Math.max(a[0], b[0]) + EPSILON &&
    Math.min(a[1], b[1]) - EPSILON <= p[1] &&
    p[1] <= Math.max(a[1], b[1]) + EPSILON
  );
}

/** geometry2d.line_intersection(segment_only=True). */
export function segmentIntersection(a1: Vec2, a2: Vec2, b1: Vec2, b2: Vec2): Vec2 | null {
  const [x1, y1] = a1;
  const [x2, y2] = a2;
  const [x3, y3] = b1;
  const [x4, y4] = b2;
  const den = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4);
  if (Math.abs(den) <= EPSILON) return null;
  const d1 = x1 * y2 - y1 * x2;
  const d2 = x3 * y4 - y3 * x4;
  const p: Vec2 = [(d1 * (x3 - x4) - (x1 - x2) * d2) / den, (d1 * (y3 - y4) - (y1 - y2) * d2) / den];
  return onSegment(a1, a2, p) && onSegment(b1, b2, p) ? p : null;
}

/** geometry2d.project_point_to_segment. */
export function projectToSegment(p: Vec2, a: Vec2, b: Vec2): [Vec2, number] {
  const dx = b[0] - a[0];
  const dy = b[1] - a[1];
  const den = dx * dx + dy * dy;
  let q: Vec2;
  if (den <= EPSILON) q = a;
  else {
    const t = Math.min(1, Math.max(0, ((p[0] - a[0]) * dx + (p[1] - a[1]) * dy) / den));
    q = [a[0] + t * dx, a[1] + t * dy];
  }
  return [q, len(p, q)];
}

function projectToLine(p: Vec2, anchor: Vec2, dir: Vec2): [Vec2, number] {
  const l = Math.hypot(dir[0], dir[1]);
  if (l <= 0) throw new Error("reference direction must have non-zero length");
  const ux = dir[0] / l;
  const uy = dir[1] / l;
  const t = (p[0] - anchor[0]) * ux + (p[1] - anchor[1]) * uy;
  const q: Vec2 = [anchor[0] + t * ux, anchor[1] + t * uy];
  return [q, len(p, q)];
}

/** Python's round(x, 12) for the tie-break key (exact halves are vanishingly rare here). */
const r12 = (x: number) => Math.round(x * 1e12) / 1e12;

function better(a: Candidate, b: Candidate): boolean {
  const ka = [r12(a.distance), PRIORITY[a.kind]];
  const kb = [r12(b.distance), PRIORITY[b.kind]];
  if (ka[0] !== kb[0]) return ka[0] < kb[0];
  if (ka[1] !== kb[1]) return ka[1] < kb[1];
  const sa = a.sourceId ?? "";
  const sb = b.sourceId ?? "";
  if (sa !== sb) return sa < sb;
  const fa = a.featureIndex ?? -1;
  const fb = b.featureIndex ?? -1;
  if (fa !== fb) return fa < fb;
  if (r12(a.point[0]) !== r12(b.point[0])) return r12(a.point[0]) < r12(b.point[0]);
  return r12(a.point[1]) < r12(b.point[1]);
}

interface Edge {
  id: string;
  index: number;
  a: Vec2;
  b: Vec2;
}

/**
 * Snap engine over a fixed set of items. Build it once per scene change and
 * call `resolve` on pointer moves.
 */
export class Snapper {
  private readonly vertices: Array<{ id: string; index: number; p: Vec2; endpoint: boolean }> = [];
  private readonly edges: Edge[] = [];

  constructor(
    items: readonly SnapItem[],
    private readonly supplemental: Partial<Record<"module_edge" | "row_edge", (box: { minX: number; minY: number; maxX: number; maxY: number }) => Array<[number, ...SupplementalEdge]>>> = {},
    exclude: Iterable<string> = []
  ) {
    const ex = new Set(exclude);
    for (const it of items) {
      if (it.visible === false || ex.has(it.id)) continue;
      const pts = it.points;
      pts.forEach((p, i) => this.vertices.push({ id: it.id, index: i, p, endpoint: !it.closed && (i === 0 || i === pts.length - 1) }));
      const n = it.closed ? pts.length : pts.length - 1;
      for (let i = 0; i < n; i++) this.edges.push({ id: it.id, index: i, a: pts[i], b: pts[(i + 1) % pts.length] });
    }
  }

  resolve(raw: Vec2, o: SnapOptions): SnapResult {
    const none: SnapResult = { raw, point: raw, applied: false, kind: null, sourceId: null, featureIndex: null, distanceM: 0 };
    const tol = o.toleranceM;
    if (tol < 0) throw new Error("toleranceM must be non-negative");
    const kinds = new Set<SnapKind>(o.enabled ?? SNAP_KINDS);
    if (o.override || kinds.size === 0) return none;

    let best: Candidate | null = null;
    const offer = (c: Candidate) => {
      if (c.distance <= tol && (!best || better(c, best))) best = c;
    };
    const near = (a: Vec2, b: Vec2) =>
      Math.min(a[0], b[0]) - tol <= raw[0] && raw[0] <= Math.max(a[0], b[0]) + tol && Math.min(a[1], b[1]) - tol <= raw[1] && raw[1] <= Math.max(a[1], b[1]) + tol;

    if (kinds.has("vertex") || kinds.has("endpoint"))
      for (const v of this.vertices) {
        const d = len(raw, v.p);
        if (d > tol) continue;
        if (kinds.has("vertex")) offer({ kind: "vertex", point: v.p, distance: d, sourceId: v.id, featureIndex: v.index });
        if (v.endpoint && kinds.has("endpoint")) offer({ kind: "endpoint", point: v.p, distance: d, sourceId: v.id, featureIndex: v.index });
      }

    if (kinds.has("midpoint") || kinds.has("edge"))
      for (const e of this.edges) {
        if (!near(e.a, e.b)) continue;
        if (kinds.has("midpoint")) {
          const m: Vec2 = [(e.a[0] + e.b[0]) / 2, (e.a[1] + e.b[1]) / 2];
          offer({ kind: "midpoint", point: m, distance: len(raw, m), sourceId: e.id, featureIndex: e.index });
        }
        if (kinds.has("edge")) {
          const [q, d] = projectToSegment(raw, e.a, e.b);
          offer({ kind: "edge", point: q, distance: d, sourceId: e.id, featureIndex: e.index });
        }
      }

    if (kinds.has("intersection")) {
      const close: number[] = [];
      this.edges.forEach((e, i) => {
        if (near(e.a, e.b)) close.push(i);
      });
      for (let x = 0; x < close.length; x++)
        for (let y = x + 1; y < close.length; y++) {
          const i = close[x];
          const j = close[y];
          const f = this.edges[i];
          const s = this.edges[j];
          if (f.id === s.id && Math.abs(f.index - s.index) <= 1) continue;
          const p = segmentIntersection(f.a, f.b, s.a, s.b);
          if (!p) continue;
          offer({ kind: "intersection", point: p, distance: len(raw, p), sourceId: `${f.id}|${s.id}`, featureIndex: i * 1_000_000 + j });
        }
    }

    for (const kind of ["module_edge", "row_edge"] as const) {
      const source = this.supplemental[kind];
      if (!kinds.has(kind) || !source) continue;
      for (const [index, id, a, b] of source({ minX: raw[0] - tol, minY: raw[1] - tol, maxX: raw[0] + tol, maxY: raw[1] + tol })) {
        const [q, d] = projectToSegment(raw, a, b);
        offer({ kind, point: q, distance: d, sourceId: id, featureIndex: index });
      }
    }

    if (kinds.has("user_grid") && o.gridSpacingM != null) {
      const g = o.gridSpacingM;
      if (g <= 0) throw new Error("gridSpacingM must be positive");
      const p: Vec2 = [pyRound(raw[0] / g) * g, pyRound(raw[1] / g) * g];
      offer({ kind: "user_grid", point: p, distance: len(raw, p), sourceId: null, featureIndex: null });
    }

    if (o.anchor && o.referenceDirection) {
      if (kinds.has("parallel")) {
        const [q, d] = projectToLine(raw, o.anchor, o.referenceDirection);
        offer({ kind: "parallel", point: q, distance: d, sourceId: null, featureIndex: null });
      }
      if (kinds.has("perpendicular")) {
        const [q, d] = projectToLine(raw, o.anchor, [-o.referenceDirection[1], o.referenceDirection[0]]);
        offer({ kind: "perpendicular", point: q, distance: d, sourceId: null, featureIndex: null });
      }
    }

    const b = best as Candidate | null;
    if (!b) return none;
    return { raw, point: b.point, applied: true, kind: b.kind, sourceId: b.sourceId, featureIndex: b.featureIndex, distanceM: b.distance };
  }
}

/** Kinds switched on in the engine-shaped snap preferences. */
export function enabledKinds(p: { enabled: boolean } & Partial<Record<SnapKind, boolean | undefined>>): SnapKind[] {
  if (!p.enabled) return [];
  return SNAP_KINDS.filter((k) => p[k] === true);
}

/** Python 3 round(): halves go to the even neighbour. */
export function pyRound(x: number): number {
  const f = Math.floor(x);
  const d = x - f;
  if (d > 0.5) return f + 1;
  if (d < 0.5) return f;
  return f % 2 === 0 ? f : f + 1;
}
